const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const userIds = ['harper_collins_664', 'harper_collins_582', 'harper_collins_686'];

userIds.forEach(uid => {
  const orders = db.prepare('SELECT order_id, status, subtotal FROM orders WHERE customer_id = ?').all(uid);
  console.log('=== User:', uid, '===');
  orders.forEach(o => {
    const fulfillments = db.prepare('SELECT item_ids FROM order_fulfillments WHERE order_id = ?').all(o.order_id);
    // Get items from fulfillments
    let itemIds = [];
    fulfillments.forEach(f => { itemIds = itemIds.concat(JSON.parse(f.item_ids)); });

    // Look up variant details for each item
    const itemDetails = itemIds.map(iid => {
      const v = db.prepare('SELECT item_id, product_id, options, price FROM rt_variants WHERE item_id = ?').get(iid);
      if (v) {
        const p = db.prepare('SELECT name FROM products WHERE product_id = ?').get(v.product_id);
        return { item_id: iid, product: p ? p.name : 'unknown', options: v.options, price: v.price };
      }
      return { item_id: iid, product: 'not found' };
    });

    console.log('  Order:', o.order_id, '| Status:', o.status, '| Subtotal:', o.subtotal);
    console.log('  Items:', JSON.stringify(itemDetails));
  });
});
