# No Python available, so let's do the modification directly via SQL
node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Current items:
// 9716794911: TrailFlex Joggers Charcoal/M @ 54.99
// 5610875649: Everyday Crew Tee White/L @ 24.99
// New items:
// 2364909101: TrailFlex Joggers Olive/M @ 53.89
// 7389318502: Everyday Crew Tee Black/L @ 23.91
// Price diff: (53.89 + 23.91) - (54.99 + 24.99) = -2.18 (refund)

const diffPrice = Math.round(((53.89 + 23.91) - (54.99 + 24.99)) * 100) / 100;
console.log('Price difference:', diffPrice);

// Begin transaction
db.transaction(() => {
  // 1. Update order status
  db.prepare(\"UPDATE orders SET status = 'pending (item modified)' WHERE order_id = '#W4705780'\").run();

  // 2. Update order_items - swap variant for TrailFlex Joggers
  db.prepare(\"UPDATE order_items SET item_id = '2364909101', unit_price = 53.89, options = '{\\\"color\\\": \\\"Olive\\\", \\\"size\\\": \\\"M\\\"}' WHERE order_id = '#W4705780' AND item_id = '9716794911'\").run();

  // 3. Update order_items - swap variant for Everyday Crew Tee
  db.prepare(\"UPDATE order_items SET item_id = '7389318502', unit_price = 23.91, options = '{\\\"color\\\": \\\"Black\\\", \\\"size\\\": \\\"L\\\"}' WHERE order_id = '#W4705780' AND item_id = '5610875649'\").run();

  // 4. Add refund payment record (diff is negative = refund)
  db.prepare(\"INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES ('#W4705780', 'refund', ?, 'paypal_5098475')\").run(Math.abs(diffPrice));
})();

// Verify the changes
console.log('\\n=== Updated Order ===');
const order = db.prepare(\"SELECT order_id, status, subtotal FROM orders WHERE order_id = '#W4705780'\").get();
console.log('Order:', order.order_id, '| Status:', order.status);

const items = db.prepare(\"SELECT item_id, name, unit_price, options FROM order_items WHERE order_id = '#W4705780'\").all();
items.forEach(i => console.log('  Item:', i.item_id, '|', i.name, '| Price:', i.unit_price, '| Options:', i.options));

const payments = db.prepare(\"SELECT transaction_type, amount, payment_method_id FROM order_payments WHERE order_id = '#W4705780'\").all();
console.log('Payment history:');
payments.forEach(p => console.log('  ' + p.transaction_type + ': \$' + p.amount + ' via ' + p.payment_method_id));
"
